void main() => runApp(const QuranApp());

class QuranApp extends StatefulWidget { const QuranApp({super.key}); @override State<QuranApp> createState() => _QuranAppState(); }
class _QuranAppState extends State<QuranApp> {
  double fs=22; bool dark=true; String reciter="عبد الباسط عبد الصمد";
  @override void initState(){ super.initState(); _load(); }
  _load() async { final p=await SharedPreferences.getInstance(); setState((){ fs=p.getDouble('fs')??22; dark=p.getBool('dark')??true; reciter=p.getString('reciter')??"عبد الباسط عبد الصمد"; }); }
  @override Widget build(BuildContext context){ return MaterialApp(debugShowCheckedModeBanner: false, theme: dark? ThemeData.dark(useMaterial3:true).copyWith(scaffoldBackgroundColor: const Color(0xFF0F0F0F)):ThemeData.light(useMaterial3:true), home: Home(fs:fs,dark:dark,reciter:reciter,onChanged:(f,d,r) async { final p=await SharedPreferences.getInstance(); await p.setDouble('fs',f); await p.setBool('dark',d); await p.setString('reciter',r); setState((){fs=f; dark=d; reciter=r;});}));}
}

class Home extends StatefulWidget { final double fs; final bool dark; final String reciter; final Function(double,bool,String) onChanged; const Home({super.key,required this.fs,required this.dark,required this.reciter,required this.onChanged}); @override State<Home> createState()=> _HomeState(); }
class _HomeState extends State<Home> { int idx=0; @override Widget build(BuildContext context){ return Scaffold(body: [SurahList(fs: widget.fs, reciter: widget.reciter), const AzkarPage(), SebhaPage(), SettingsPage(fs: widget.fs, dark: widget.dark, reciter: widget.reciter, onChanged: widget.onChanged)][idx], bottomNavigationBar: BottomNavigationBar(currentIndex: idx, onTap:(i)=>setState(()=>idx=i), selectedItemColor: const Color(0xFFD4AF37), backgroundColor: const Color(0xFF1A1A1A), type: BottomNavigationBarType.fixed, items: const [BottomNavigationBarItem(icon: Icon(Icons.menu_book),label:"القرآن"),BottomNavigationBarItem(icon: Icon(Icons.favorite),label:"أدعية"),BottomNavigationBarItem(icon: Icon(Icons.circle),label:"تسبيح"),BottomNavigationBarItem(icon: Icon(Icons.settings),label:"الاعدادات")])); } }

// قائمة السور
class SurahList extends StatelessWidget { final double fs; final String reciter; const SurahList({super.key,required this.fs,required this.reciter}); @override Widget build(BuildContext context){ return Scaffold(appBar: AppBar(title: const Text("القرآن الكريم"), centerTitle:true, backgroundColor: const Color(0xFF151515)), body: ListView.builder(itemCount:114,itemBuilder:(c,i){int n=i+1; return Card(color: const Color(0xFF1E1E1E), margin: const EdgeInsets.symmetric(horizontal:10,vertical:4), child: ListTile(leading: Container(width:45,height:45,decoration: BoxDecoration(color: const Color(0xFFD4AF37), borderRadius: BorderRadius.circular(10)), child: Center(child: Text("$n",style: const TextStyle(color:Colors.black,fontWeight:FontWeight.bold)))), title: Text(quran.getSurahNameArabic(n), style: const TextStyle(color: Colors.white,fontWeight:FontWeight.bold)), subtitle: Text("${quran.getSurahName(n)} - ${quran.getVerseCount(n)} آية", style: const TextStyle(color: Colors.white38,fontSize:11)), trailing: const Icon(Icons.play_circle_fill,color: Color(0xFFD4AF37),size:30), onTap: ()=> Navigator.push(c, MaterialPageRoute(builder:(_)=> ReaderPage(surah:n, fs:fs, reciter:reciter))))); })); } }

// صفحة القراءة - اذا تطب على الآية تطلع كاملة + مرقمة + صوت
class ReaderPage extends StatefulWidget { final int surah; final double fs; final String reciter; const ReaderPage({super.key,required this.surah,required this.fs,required this.reciter}); @override State<ReaderPage> createState()=> _ReaderPageState(); }
class _ReaderPageState extends State<ReaderPage> {
  final player=AudioPlayer(); bool playing=false, loading=false; int cur=0; late String rec;
  final codes={"عبد الباسط عبد الصمد":"Abdul_Basit_Murattal_192kbps","محمد صديق المنشاوي":"Minshawy_Murattal_128kbps","ياسر الدوسري":"Yasser_Ad-Dosari_128kbps"};
  @override void initState(){ super.initState(); rec=widget.reciter; player.currentIndexStream.listen((i){ if(i!=null) setState(()=>cur=i+1); }); player.playerStateStream.listen((s){ if(s.processingState==ProcessingState.completed) setState((){playing=false; cur=0;}); }); }
  playFull() async { if(playing){ await player.pause(); setState(()=>playing=false); return; } if(player.audioSource!=null && cur>0){ await player.play(); setState(()=>playing=true); return; } setState(()=>loading=true); try{ int cnt=quran.getVerseCount(widget.surah); List<AudioSource> src=[]; for(int i=1;i<=cnt;i++){ String sid=widget.surah.toString().padLeft(3,'0'); String vid=i.toString().padLeft(3,'0'); src.add(AudioSource.uri(Uri.parse("https://everyayah.com/data/${codes[rec]}/$sid$vid.mp3"))); } await player.setAudioSource(ConcatenatingAudioSource(children:src)); await player.play(); setState(()=>{playing=true,loading=false,cur=1}); }catch(e){ setState(()=>loading=false); ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text("يحتاج انترنت لتشغيل الصوت"))); } }
  playOne(int verse) async { setState(()=>loading=true); try{ String sid=widget.surah.toString().padLeft(3,'0'); String vid=verse.toString().padLeft(3,'0'); await player.setAudioSource(AudioSource.uri(Uri.parse("https://everyayah.com/data/${codes[rec]}/$sid$vid.mp3"))); await player.play(); setState(()=>{playing=true,loading=false,cur=verse}); }catch(e){ setState(()=>loading=false); } }
  @override void dispose(){ player.dispose(); super.dispose(); }
  @override Widget build(BuildContext context){
    int cnt=quran.getVerseCount(widget.surah);
    return Scaffold(appBar: AppBar(title: Text(quran.getSurahNameArabic(widget.surah)), actions: [PopupMenuButton<String>(onSelected:(v)=>setState(()=>rec=v), itemBuilder:(_)=>["عبد الباسط عبد الصمد","محمد صديق المنشاوي","ياسر الدوسري"].map((e)=>PopupMenuItem(value:e,child:Text(e))).toList(), child: Padding(padding: const EdgeInsets.all(12), child: Text(rec,style: const TextStyle(fontSize:10)))))]),
      body: Column(children: [
        Container(padding: const EdgeInsets.all(10), color: const Color(0xFF1A1A1A), child: Row(children: [loading? const CircularProgressIndicator(color: Color(0xFFD4AF37)):IconButton(icon: Icon(playing?Icons.pause_circle:Icons.play_circle,size:50,color: const Color(0xFFD4AF37)),onPressed: playFull), const SizedBox(width:8), Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(playing? "الآن: الآية $cur":"تشغيل السورة كاملة",style: const TextStyle(color:Colors.white,fontSize:12)), Text(rec,style: const TextStyle(color:Colors.white38,fontSize:10))]))])),
        Expanded(child: ListView.builder(padding: const EdgeInsets.all(10), itemCount: cnt+1, itemBuilder:(c,i){
          if(i==cnt){ return Container(margin: const EdgeInsets.only(top:25,bottom:30), padding: const EdgeInsets.all(18), decoration: BoxDecoration(color: Colors.black, borderRadius: BorderRadius.circular(15), border: Border.all(color: const Color(0xFFD4AF37),width:1.5)), child: Column(children: const [Text("صدقة جارية",style: TextStyle(color: Color(0xFFD4AF37))), Text("الفاتحة الى روح المرحوم",style: TextStyle(color: Colors.white70)), Text("ناصر عزيز",style: TextStyle(color: Colors.white,fontSize:26,fontWeight:FontWeight.bold)), SizedBox(height:10), Divider(color: Color(0xFFD4AF37)), SizedBox(height:8), Text("بِسْمِ اللهِ الرَّحْمٰنِ الرَّحِيمِ\nالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ\nالرَّحْمٰنِ الرَّحِيمِ\nمَالِكِ يَوْمِ الدِّينِ\nإِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ\nاهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ\nصِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ", textAlign: TextAlign.center, style: TextStyle(color: Colors.white,height:1.9,fontSize:18)), SizedBox(height:10), Text("اللهم اجعل ثواب ما قرأناه في ميزان حسناته",style: TextStyle(color: Colors.white38,fontSize:11))]));
          }
          bool sel=cur==i+1 && playing;
          String verseText=quran.getVerse(widget.surah, i+1, verseEndSymbol:false);
          return GestureDetector(onTap: ()=> playOne(i+1), child: Container(margin: const EdgeInsets.only(bottom:6), padding: const EdgeInsets.all(14), decoration: BoxDecoration(color: sel? const Color(0xFFD4AF37).withOpacity(0.15): const Color(0xFF1E1E1E), borderRadius: BorderRadius.circular(12), border: Border.all(color: sel? const Color(0xFFD4AF37):Colors.transparent)), child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [Text(verseText, textAlign: TextAlign.right, style: TextStyle(fontSize: widget.fs,height:1.9,color: sel? const Color(0xFFD4AF37):Colors.white)), const SizedBox(height:8), Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [Container(padding: const EdgeInsets.symmetric(horizontal:10,vertical:3), decoration: BoxDecoration(color: sel? const Color(0xFFD4AF37):Colors.white10, borderRadius: BorderRadius.circular(20)), child: Text("آية ${i+1}", style: TextStyle(fontSize:11,color: sel?Colors.black:Colors.white70))), Row(children: [Text(quran.getVerseEndSymbol(i+1), style: TextStyle(color: sel? const Color(0xFFD4AF37):Colors.white38)), const SizedBox(width:6), const Icon(Icons.volume_up,size:16,color: Colors.white38)])])])));
        })),
      ]));
  }
}

